/*
 * A233388  Odious numbers that are the sum of 2 consecutive odious numbers.
 * https://oeis.org/A233388
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = the n-th odious number that can be written as the sum of
 *            two consecutive odious numbers. An odious number has an odd
 *            number of 1‑bits in its binary representation. The sequence is
 *            generated by scanning the odious numbers in increasing order,
 *            taking each consecutive pair, computing their su...
 * Range:     u8 n <= 21, u16 n <= 5461, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

/* Helper: test whether x has an odd popcount (is odious). */
static bool is_odious(seq_t x)
{
    unsigned int parity = 0;
    while (x) {
        parity ^= (unsigned int)(x & 1);
        x >>= 1;
    }
    return parity;
}

/* Main sequence function. */
seq_t a(idx_t n)
{
    /* Static state to keep the computed odious numbers. */
    static seq_t *odious = NULL;      /* array of odious numbers */
    static size_t odious_len = 0;     /* number of elements stored   */
    static size_t odious_cap = 0;     /* allocated capacity          */
    static seq_t last_candidate = 0;  /* last number examined        */
    static bool initialized = false;

    if (!initialized) {
        odious_cap = 4;
        odious = (seq_t *)malloc(odious_cap * sizeof(seq_t));
        odious_len = 0;
        last_candidate = 0;
        initialized = true;
    }

    size_t found = 0;   /* number of valid sums found so far */
    size_t i = 0;       /* index of the first element in the pair */

    while (found < n) {
        /* Ensure we have at least odious[i+1] available. */
        while (odious_len <= i + 1) {
            /* Find the next odious number after last_candidate. */
            seq_t cand = last_candidate + 1;
            while (!is_odious(cand)) {
                cand += 1;
            }
            /* Grow the array if necessary. */
            if (odious_len >= odious_cap) {
                odious_cap = odious_cap ? odious_cap * 2 : 4;
                odious = (seq_t *)realloc(odious, odious_cap * sizeof(seq_t));
            }
            odious[odious_len++] = cand;
            last_candidate = cand;
        }

        /* Compute the sum of the consecutive pair. */
        seq_t sum = odious[i] + odious[i + 1];

        /* If the sum is odious, record it. */
        if (is_odious(sum)) {
            found++;
            if (found == n) {
                return sum;
            }
        }

        i++;   /* move to the next pair */
    }

    /* In theory this point is unreachable because the sequence is infinite. */
    return 0;
}
